actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate SC state additions
            double additions = 0.0;

            // SC requires addback of:
            // - Federal interest income (taxable to SC)
            // - IRC 199A deduction (SC does not conform)
            // - State income tax refunds
            // - Certain bonus depreciation amounts (depends on year)

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.section_199a_deduction;
            // additions += result.state_tax_refunds;

            apportionment.state_additions = additions;

            // Calculate SC state subtractions
            double subtractions = 0.0;

            // SC allows subtraction of:
            // - SC municipal bond interest (exempt for SC purposes)
            // - SC net operating loss deduction (if applicable)
            // - Certain dividend income (85% dividend received deduction)

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.sc_municipal_interest;
            // subtractions += result.sc_nol_deduction;
            // subtractions += result.sc_dividend_deduction;

            apportionment.state_subtractions = subtractions;

            // SC uses 5% flat rate
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract SC state credits
            // SC offers various credits: job development, corporate headquarters,
            // port volume increase, R&D, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Add SC annual license fee
            // License fee = 0.1% of capital and paid-in surplus, minimum $15
            // Note: This would need entity fields for capital and paid-in surplus
            // For now, we apply minimum license fee
            double license_fee = apportionment.license_fee_minimum;
            // If capital data available:
            // license_fee = Math.max(apportionment.license_fee_minimum,
            //                       corporation.capital_and_surplus * apportionment.license_fee_rate);

            apportionment.state_tax += license_fee;

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // No income tax, but license fee still applies
            double license_fee = apportionment.license_fee_minimum;
            // If capital data available:
            // license_fee = Math.max(apportionment.license_fee_minimum,
            //                       corporation.capital_and_surplus * apportionment.license_fee_rate);

            apportionment.state_tax = license_fee;
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
